def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M = data[0], data[1]
    A = data[2:2 + N]
    B = data[2 + N:2 + N + N - 1]

    C = [(B[i] - A[i] - A[i + 1]) % M for i in range(N - 1)]

    d = 0
    odd_t = []
    even_d = []
    total_d = 0

    for i in range(N):
        dm = d % M
        total_d += dm

        if i % 2 == 0:
            odd_t.append(M - dm)
        else:
            even_d.append(dm)

        if i < N - 1:
            d = C[i] - d

    coef = 1 if N % 2 == 1 else 0

    odd_t.sort()
    even_d.sort()

    def value(t):
        even_less = bisect_left(even_d, t)
        odd_ge = bisect_right(odd_t, t)
        return coef * t + total_d + M * (even_less - odd_ge)

    candidates = {0, M - 1}

    for x in even_d:
        e = x + 1
        if e <= M - 1:
            candidates.add(e)

    for t in odd_t:
        if t <= M - 1:
            candidates.add(t)

    ans = min(value(t) for t in candidates)
