import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    edges = set()
    idx = 2

    for _ in range(M):
        a = data[idx]
        b = data[idx + 1]
        idx += 2
        if a > b:
            a, b = b, a
        edges.add((a, b))

    E = len(edges)

    deg = [0] * (N + 1)
    for a, b in edges:
        deg[a] += 1
        deg[b] += 1

    freq = [0] * (N + 1)
    for v in range(1, N + 1):
        freq[deg[v]] += 1

    # Count unordered pairs of vertices whose degree sum is E.
    P = 0
    for x in range(0, E // 2 + 1):
        y = E - x
        if x > N or y > N:
            continue
        if x < y:
            P += freq[x] * freq[y]
        elif x == y:
            P += freq[x] * (freq[x] - 1) // 2

    # Count edges whose degree sum is E and E + 1.
    edge_sum_E = 0
    edge_sum_Eplus1 = 0

    for a, b in edges:
        s = deg[a] + deg[b]
        if s == E:
            edge_sum_E += 1
        if s == E + 1:
            edge_sum_Eplus1 += 1

    ans = P - edge_sum_E + edge_sum_Eplus1
    print(ans)

