import sys

MOD = 998244353
INV2 = (MOD + 1) // 2

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2].decode()

    parent = list(range(N))
    dsu_size = [1] * N

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if dsu_size[ra] < dsu_size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        dsu_size[ra] += dsu_size[rb]

    idx = 3
    for _ in range(M):
        a = int(data[idx]) - 1
        b = int(data[idx + 1]) - 1
        idx += 2
        union(a, b)

    comps = {}
    for i in range(N):
        r = find(i)
        comps.setdefault(r, []).append(i)

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    total = 1
    has_duplicate = False

    for positions in comps.values():
        c = len(positions)
        freq = [0] * 26

        for p in positions:
            freq[ord(S[p]) - ord('a')] += 1

        dup = False
        ways = fact[c]
        for f in freq:
            if f > 1:
                dup = True
            ways = ways * invfact[f] % MOD

        total = total * ways % MOD
        if dup:
            has_duplicate = True

    if has_duplicate:
        ans = total
    else:
        ans = total * INV2 % MOD

    print(ans)

if __name__ == "__main__":
    main()

